WITH by_dimension AS (SELECT o.status AS order_status, e.carrier, COUNT(*) AS cnt, MAX(e.cost) AS max_cost, GROUPING_ID() AS level_id FROM shipments e INNER JOIN orders o ON e.order_id = o.id GROUP BY CUBE (o.status, e.carrier)) SELECT order_status, carrier, cnt, max_cost, level_id, CASE WHEN carrier RLIKE '^(Flash|UPS)$' THEN 'CORE' WHEN carrier RLIKE '^(DHL|FedEx)$' THEN 'EXTENDED' ELSE 'GROUP_B' END AS carrier_zone FROM by_dimension
